import{_ as i,H as a,f as o,i as t}from"./chunks/framework.BauLNg70.js";const p=JSON.parse('{"title":"Publishing your mod","description":"","frontmatter":{},"headers":[],"relativePath":"publishing.md","filePath":"publishing.md"}'),s={name:"publishing.md"};function r(l,e,n,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="publishing-your-mod" tabindex="-1">Publishing your mod <a class="header-anchor" href="#publishing-your-mod" aria-label="Permalink to &quot;Publishing your mod&quot;">​</a></h1><p>How to publish a finished mod to Steam Workshop, maintain releases, and qualify for verification tiers.</p><hr><h2 id="before-publishing-—-checklist" tabindex="-1">Before publishing — checklist <a class="header-anchor" href="#before-publishing-—-checklist" aria-label="Permalink to &quot;Before publishing — checklist&quot;">​</a></h2><ul><li>[ ] Tested in local sideload with the current game version.</li><li>[ ] Tested with at least 1 other mod active simultaneously (to catch interactions).</li><li>[ ] Tested after game restart (state persisted correctly).</li><li>[ ] Tested with/without DLCs declared in <code>requires.dlcs</code>.</li><li>[ ] Valid <code>mod.json</code> (<code>pnpm exec mod-validator</code> or similar provided by the studio&#39;s SDK if it exists).</li><li>[ ] Icons / screenshots prepared (PNG, &lt;500KB each).</li><li>[ ] <code>metadata.description</code> clear, no typos.</li><li>[ ] Changelog written (if update of previous version).</li><li>[ ] License declared (MIT, GPL, custom...).</li></ul><hr><h2 id="steam-workshop-—-process" tabindex="-1">Steam Workshop — process <a class="header-anchor" href="#steam-workshop-—-process" aria-label="Permalink to &quot;Steam Workshop — process&quot;">​</a></h2><h3 id="_1-package" tabindex="-1">1. Package <a class="header-anchor" href="#_1-package" aria-label="Permalink to &quot;1. Package&quot;">​</a></h3><p>Create a <code>.zip</code> with the structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-mod.zip</span></span>
<span class="line"><span>├── mod.json</span></span>
<span class="line"><span>├── dist/</span></span>
<span class="line"><span>│   └── mod.js</span></span>
<span class="line"><span>├── assets/</span></span>
<span class="line"><span>│   ├── icon.png</span></span>
<span class="line"><span>│   └── screenshots/</span></span>
<span class="line"><span>└── locales/</span></span></code></pre></div><p>Recommended max size: 5 MB. Workshop accepts more but slow downloads penalize you.</p><h3 id="_2-steam-workshop-client" tabindex="-1">2. Steam Workshop client <a class="header-anchor" href="#_2-steam-workshop-client" aria-label="Permalink to &quot;2. Steam Workshop client&quot;">​</a></h3><p>From Steam, open the game (Snake Classic or equivalent) → menu → Workshop → &quot;Create New Item&quot;. Upload the <code>.zip</code>.</p><p>Fields:</p><ul><li><strong>Title</strong>: <code>metadata.name</code> by default.</li><li><strong>Description</strong>: paste a README with sections (what it does, screenshots, changelog).</li><li><strong>Visibility</strong>: public / friends only / unlisted.</li><li><strong>Tags</strong>: use the ones from the game&#39;s catalog (the studio defines them).</li></ul><h3 id="_3-submit" tabindex="-1">3. Submit <a class="header-anchor" href="#_3-submit" aria-label="Permalink to &quot;3. Submit&quot;">​</a></h3><p>After successful upload, the Workshop ID is generated. <strong>Save it</strong> — you&#39;ll need it later for updates.</p><h3 id="_4-verification-optional" tabindex="-1">4. Verification (optional) <a class="header-anchor" href="#_4-verification-optional" aria-label="Permalink to &quot;4. Verification (optional)&quot;">​</a></h3><p>The studio may offer a &quot;modder verification&quot; flow:</p><ul><li>Apply via form.</li><li>Pass malware detection test on your mod.</li><li>Accept specific TOS.</li><li>Receive a signing key or flag that raises your trust tier to <code>workshopVerified</code>.</li></ul><p>Verified mods:</p><ul><li>No prompt to the player on activation.</li><li>Standard permissions granted without extra confirmation.</li><li>&quot;Verified&quot; banner visible in Workshop and in the game&#39;s settings.</li></ul><hr><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>To publish a new version:</p><ol><li>Bump <code>version</code> in <code>mod.json</code> (PATCH / MINOR / MAJOR according to changes).</li><li>Package the new <code>.zip</code>.</li><li>In Steam Workshop, open your existing item → &quot;Update Item&quot; → upload the new zip.</li><li>Add a changelog entry.</li></ol><p>Automatic update for players:</p><ul><li>If they had <code>1.0.0</code> and you publish <code>1.1.0</code> (MINOR): their settings are preserved.</li><li>If you publish <code>2.0.0</code> (MAJOR): the player&#39;s client <strong>resets</strong> the mod&#39;s settings automatically on update (announce it in the changelog).</li></ul><hr><h2 id="sideload-distribution" tabindex="-1">Sideload distribution <a class="header-anchor" href="#sideload-distribution" aria-label="Permalink to &quot;Sideload distribution&quot;">​</a></h2><p>If your mod isn&#39;t going to Steam Workshop (private mod, closed beta, playtest):</p><ol><li>Distribute the <code>.zip</code> via your channels (GitHub releases, web page, Discord, etc.).</li><li>The player extracts to <code>&lt;userData&gt;/&lt;gameId&gt;/mods/&lt;modId&gt;/</code>.</li><li>Restart the game.</li></ol><p>Sideload mods are <code>unsigned</code> unless you sign with a declared public key (advanced — see manual signing with <code>ed25519</code> in <a href="https://github.com/leteoworks/my-game-fw/blob/main/docs/mods/security/signing-and-trust.md" target="_blank" rel="noreferrer">../security/signing-and-trust.md</a>).</p><hr><h2 id="versioning-and-compatibility" tabindex="-1">Versioning and compatibility <a class="header-anchor" href="#versioning-and-compatibility" aria-label="Permalink to &quot;Versioning and compatibility&quot;">​</a></h2><p>When the game announces a new MAJOR version:</p><ul><li>Your mod with <code>requires.hostApi: &#39;^1.0.0&#39;</code> is marked <code>incompatible</code> with game v2.x.</li><li>You&#39;ll probably need to rewrite parts that depended on the old host API. Check the <code>host-api-changelog</code>.</li><li>Publish <code>2.0.0</code> (MAJOR of your mod) with <code>requires.hostApi: &#39;^2.0.0&#39;</code>.</li></ul><p>Players with the old game version can keep using your mod v1.x; those who upgraded to v2.x download your v2.0.0.</p><p>Workshop handles delivery of compatible versions automatically if you declared the ranges correctly.</p><hr><h2 id="if-your-mod-enters-quarantine" tabindex="-1">If your mod enters quarantine <a class="header-anchor" href="#if-your-mod-enters-quarantine" aria-label="Permalink to &quot;If your mod enters quarantine&quot;">​</a></h2><p>The framework marks mods that fail repeatedly as <code>quarantined</code>. Players see a &quot;This mod failed — the author may have published a fix&quot; message. Your job:</p><ol><li>Reproduce the fault locally with the latest game version.</li><li>Fix.</li><li>Publish a new version (PATCH bump).</li><li>Communicate on the Workshop page: &quot;v1.2.4 fixes the v1.2.3 crash&quot;.</li></ol><p>Players un-quarantine manually from settings after updating. The framework does not auto-un-quarantine.</p><hr><h2 id="if-you-receive-security-reports" tabindex="-1">If you receive security reports <a class="header-anchor" href="#if-you-receive-security-reports" aria-label="Permalink to &quot;If you receive security reports&quot;">​</a></h2><p>If someone reports that your mod might have a security issue (leaking data, making undeclared requests, etc.):</p><ol><li><strong>Take it seriously</strong> even if it seems minor.</li><li>Audit your code.</li><li>Publish a fix.</li><li>Communicate transparently in your changelog.</li></ol><p>If the reports are valid and serious, the studio can kill-switch your mod remotely (shut down on clients without update). That usually means the end of the relationship with the platform.</p><hr><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><ul><li>Exhaustive checklist before each release.</li><li>Workshop process direct from the Steam client.</li><li>Optional verification flow raises your trust tier.</li><li>Strict SemVer on updates.</li><li>Quarantine recoverable with a fix.</li><li>Security non-compliance → terminal kill-switch.</li></ul>`,52)])])}const m=i(s,[["render",r]]);export{p as __pageData,m as default};
